-- GENERATED by `wfi generate` from data/quest/quest-0003.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [3100] = { "Simple Letter", "Leggi la Simple Letter e parla con Llane Beshere nella Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Llane, il nostro istruttore dei guerrieri. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ah, hai ricevuto la mia lettera, {name}... bene.\n\nUltimamente sono arrivati parecchi guerrieri a Elwynn: un bene per Stormwind, ma un male per i kobold e i Defias della zona.", "Sistemati per bene, impara a conoscere il territorio e torna da me ogni volta che hai bisogno di addestramento. Sarò qui giorno e notte.\n\nI Knights of the Silver Hand hanno fatto un buon lavoro per rendere questo posto abbastanza sicuro, ma quando conoscerai gli altri cittadini, credo che scoprirai che tutti hanno qualche problema per cui servirebbe una mano: una mano che proprio tu, come {class}, puoi dar loro. Buona fortuna.", 0x8a6765ad, 0xcd1a2f24, 0xfe579234, 0x76e67b55, 0x1ce50385, "....." },
  [3101] = { "Consecrated Letter", "Leggi la Consecrated Letter e parla con Brother Sammuel nella Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Brother Sammuel, il nostro istruttore dei paladini. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Finalmente! Ci incontriamo faccia a faccia, da fratello a <fratello/sorella>. Ti do il benvenuto a Northshire. Questa sarà la tua casa per un po', mentre impari come vanno le cose, ma sappi che Stormwind non è lontana e prima o poi il tuo cammino ti porterà là. Fino ad allora, sii paziente... Knight of the Silver Hand.", "Nel frattempo, dovresti sapere un paio di cose. Per molti, in questa terra, sei un simbolo: comportati di conseguenza. La Sacra Luce splende dentro di te, e sarà evidente sia ai tuoi alleati sia ai tuoi nemici.\n\nInoltre, man mano che crescerai in saggezza e potere, dovrai addestrarti per imparare nuove abilità. È qui che entro in gioco io. Quando sentirai di aver fatto un po' di esperienza qui a Northshire, torna da me e ti insegnerò ciò che penso tu sia <pronto/pronta> a imparare. Buona fortuna... {class}!", 0x339c82f5, 0x6d6ee593, 0x26cd99ad, 0xeb1b3e11, 0x8b941ae4, ".....", nil, nil, nil, 0x808f8fbe, nil },
  [3102] = { "Encrypted Letter", "Leggi l'Encrypted Letter e parla con Jorik Kerridan nella stalla dietro la Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Jorik, uno dei nostri istruttori. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ce l'hai fatta ad arrivare fin qui senza un graffio, e non sembra che ti abbiano visto in molti. Per me basta così. Non mi piace attirare troppa attenzione qui dietro... bello tranquillo. Sono sicuro che capisci.\n\nHai già avuto problemi? Bene, mi fa piacere. Presto le cose cambieranno.", "Scoprirai che parecchie organizzazioni ambiscono alle nostre abilità, {name}. Avventurieri, SI:7... diamine, perfino la Defias Brotherhood non disdegnerebbe una spia o due dentro Stormwind. Ma ricordati questo: nessuno decide per te. Non lasciare che qualcuno ti costringa a fare qualcosa che non vuoi! E poi, tutte le carte le abbiamo in mano noi... almeno finché la partita non è finita. Capisci cosa intendo?\n\nComunque, volevo solo presentarmi e farti sapere che sono qui se hai bisogno di addestramento. Passa quando vuoi.", 0x5eef0cde, 0x3d129a05, 0xb39f75e7, 0x6b9b0e24, 0xd57ec303, ".....", nil, nil, nil, nil, 0x46913652 },
  [3103] = { "Hallowed Letter", "Leggi la Hallowed Letter e parla con Priestess Anetta nella Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Priestess Anetta, la nostra istruttrice dei sacerdoti. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ah, finalmente eccoti. Sapevo che avresti trovato la strada fino a me. La Sacra Luce splende su di te e sul cammino che hai scelto. Sono tempi duri: la Burning Legion è ancora presente su Azeroth, l'intero Kalimdor cerca nuovi modi per difendersi dalle proprie tribolazioni, e spetta a te aiutare quante più persone puoi.", "Man mano che acquisirai esperienza, torna da me e farò il possibile per trasmetterti il mio sapere. Fino ad allora, va' con la compassione nel cuore, e lascia che la saggezza ti guidi. Ricorda: il mondo diventa un posto migliore solo se sei tu a renderlo tale.", 0x3871ce99, 0x3719f745, 0x63ba8573, 0x3c6b09ac, 0x69805596, "....." },
  [3104] = { "Glyphic Letter", "Leggi la Glyphic Letter e parla con Khelden Bremen dentro la Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Khelden, il nostro istruttore dei maghi. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Salve, {name}. Sono Khelden. Posso fare qualcosa per te?", "Ah ah, sapevo che il mio biglietto non ti avrebbe distolto dal tuo cammino. Quindi sei <pronto/pronta>, vero? <Pronto/Pronta> ad accettare il tuo destino? <Pronto/Pronta> a sfidare gli dei e qualsiasi altra forza ti si pari davanti nella ricerca del sapere e del potere?\n\nNon ti mentirò, {name}: sarai <temuto/temuta> quanto <rispettato/rispettata>. Ma sappi anche questo: io sarò qui per te quando avrai bisogno di addestramento. Basta che tu mi cerchi man mano che diventi più potente.", 0x9c0b51a2, 0xb2702f67, 0xde444377, 0x1257130c, 0xea282e3b, "....." },
  [3105] = { "Tainted Letter", "Leggi la Tainted Letter e parla con Drusilla La Salle accanto alla Northshire Abbey.", "Mi hanno chiesto di fartela avere appena fossi di ritorno dagli accampamenti dei kobold, {name}. Sembra una lettera sigillata con l'insegna di Drusilla, una delle nostre istruttrici. Io la leggerei senza esitare, prima di occuparmi di qualsiasi altra faccenda qui all'abbazia.", "Ah, eccoti qui, e appena in tempo, {name}. Poco fa alcune guardie erano qui e mi guardavano con curiosità... patetici profani.", "Man mano che il tuo potere cresce, sarai <tentato/tentata>: devi sempre ricordarti di controllarti. Non ti mentirò: la corruzione può colpire chiunque pratichi l'arcano, soprattutto chi ha a che fare con le creature del Twisting Nether. Sii paziente e prudente... ma non lasciare che questo soffochi la tua ambizione.\n\nQuando sarai più potente, torna da me e ti insegnerò di più sulle nostre vie.", 0xfe092140, 0xa2b9450e, 0xc0471a03, 0x04538110, 0x1fcadfe2, "....." },
  [3903] = { "Milly Osworth", "Parla con Milly Osworth.", "Hai dimostrato di essere affidabile come {class}, {name}. Affidabile, e senza paura di sporcarti le mani, eh?\n\nHo un'amica, Milly Osworth, che è nei guai. È dall'altra parte dell'abbazia con il suo carro, vicino alla stalla. Sono sicuro che un paio di mani come le tue le farebbero comodo.", nil, "Oh, è stato Deputy Willem a dirti di parlare con me? È un uomo coraggioso e sempre pronto ad aiutare, ma i suoi doveri lo tengono bloccato alla Northshire Abbey e temo che il problema che ho oggi sia al di là delle sue possibilità.\n\nForse puoi aiutarmi tu?", 0xe1f36bcd, 0xf258ab38, 0x7ad88966, nil, 0xcb7f07d4, "...m." },
  [3904] = { "Milly's Harvest", "Porta 8 casse di Milly's Harvest a Milly Osworth, alla Northshire Abbey.", "Una banda di briganti, i Defias, si è insediata nei Northshire Vineyards mentre facevo la vendemmia! L'ho riferito alle guardie di Northshire e mi hanno assicurato che se ne sarebbero occupate, ma... temo per il mio raccolto d'uva! Se non me la rubano i Defias, ho paura che la calpestino le guardie mentre scacciano quei delinquenti.\n\nTi prego, devi aiutarmi! Ho raccolto quasi tutta l'uva nei secchi, ma li ho lasciati nei vigneti a sud-est.\n\nPortami quelle casse! Salva il mio raccolto!", "Hai il mio raccolto, {name}?", "Oh, grazie, {name}! Hai salvato il mio raccolto! E spero che tu abbia fatto capire a qualcuno di quei Defias che qui non possono creare guai.\n\nSaremo anche a corto di guardie di questi tempi, ma siamo fortunati ad avere eroi come te a proteggerci!", 0xb7c26a3d, 0x92647f37, 0x0fa99512, 0x44af6d31, 0xbc754155, "....." },
  [3905] = { "Grape Manifest", "Porta il Grape Manifest a Brother Neals, nella Northshire Abbey.", "Ora che il mio raccolto è salvo, porta questo Grape Manifest a Brother Neals. Gestisce le scorte di cibo e bevande di Northshire, e sono certa che sarà felicissimo di sapere che ha dell'uva fresca.\n\nTroverai Brother Neals nell'abbazia, nel campanile... dove gli piace assaggiare il suo vino.", "Mi sembri di ottimo umore! Vieni! Siediti e bevi qualcosa!", "Vediamo un po'...\n\nOh, cielo! L'uva di Milly è salva! Quando mi ha detto che i briganti avevano invaso i suoi vigneti stavo quasi per disperare, ma la mia fede nella Luce non ha vacillato!\n\nE grazie al tuo coraggio, ora abbiamo uva per altro vino! Che la Luce ti benedica, {name}, e ti protegga!", 0x46e6ddee, 0x54a8efd7, 0x7e4adc7b, 0x920c46b4, 0x8ad49c5d, "....." },
})
